const icons={home:'<path d="m3 10 9-7 9 7v10H14v-6h-4v6H3Z"/>',folder:'<path d="M3 6h6l2 3h10v11H3Z"/>',users:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-4a6 6 0 0 1 12 0v4M16 4a3 3 0 0 1 0 6m2 3a5 5 0 0 1 3 5v3"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18"/>',chart:'<path d="M5 21V11m7 10V3m7 18V7"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',bell:'<path d="M5 17h14l-2-4V8a5 5 0 0 0-10 0v5ZM10 21h4"/>',plus:'<path d="M12 4v16M4 12h16"/>',check:'<rect x="3" y="3" width="18" height="18" rx="5"/><path d="m7 12 3 3 7-7"/>'};
const icon=n=>'<svg viewBox="0 0 24 24" aria-hidden="true">'+(icons[n]||icons.folder)+'</svg>';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

'use strict';
const stages=['Briefing','Em produção','Em aprovação','Concluído'],services=['Vídeo','Social media','Design','Outro'];
const labels={overview:'Visão geral',projects:'Projetos',clients:'Clientes',agenda:'Agenda',planning:'Planejamento',finance:'Financeiro',settings:'Dados e backup',account:'Perfil e integrações'};
let userProfile={},googleState={configured:false,connected:false,forms:[],calendarLinks:[]};
let plans=[],planItems=[],productionStates=[],selectedPlanId=null;
let clients=[],projects=[],tasks=[],view='overview',filter='Todos',query='',showArchived=false,busy=false,loaded=false,toastTimer,modalProjectId=null,lastFocus=null;
const dialog=document.getElementById('project-dialog'),content=document.getElementById('content');
const money=n=>Number(n/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
function today(){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());return ['year','month','day'].map(k=>parts.find(p=>p.type===k).value).join('-')}
function offsetDate(day,n){const date=new Date(day+'T12:00:00Z');date.setUTCDate(date.getUTCDate()+n);return date.toISOString().slice(0,10)}
const dateLabel=d=>d===today()?'Hoje':new Date(d+'T12:00:00Z').toLocaleDateString('pt-BR',{day:'2-digit',month:'short',year:'numeric',timeZone:'America/Sao_Paulo'});
const clientName=id=>clients.find(c=>c.id===id)?.name||'Cliente não encontrado';
const initials=n=>n.trim().split(/\s+/).slice(0,2).map(w=>w[0]).join('').toUpperCase();
const avatar=c=>'<span class="avatar" style="background:'+['#e8b9bc','#e6c19b','#b6d3e3','#ddd6bc'][c.id%4]+'">'+esc(initials(c.name))+'</span>';
const projectTasks=id=>tasks.filter(t=>t.projectId===id);
function progress(p){const ts=projectTasks(p.id);return p.stage==='Concluído'?100:ts.length?Math.round(ts.filter(t=>t.done).length/ts.length*100):0}
const activeProjects=()=>projects.filter(p=>!p.archived);
const filtered=()=>projects.filter(p=>(showArchived||!p.archived)&&(filter==='Todos'||p.service===filter)&&(p.title+' '+clientName(p.clientId)).toLocaleLowerCase('pt-BR').includes(query.toLocaleLowerCase('pt-BR')));
function toast(text){const t=document.getElementById('toast');t.textContent=text;t.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.hidden=true,4500)}
async function request(path,data){const res=await fetch('/api/'+path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const result=await res.json();if(!res.ok)throw new Error(result.error||'Não foi possível salvar.');return result}
async function refresh(){const res=await fetch('/api/data',{cache:'no-store'});if(!res.ok)throw new Error('Não foi possível ler os dados. Verifique se o Studio está aberto.');const data=await res.json();clients=data.clients;projects=data.projects;tasks=data.tasks;plans=data.plans||[];planItems=data.planItems||[];productionStates=data.productionSteps||[];userProfile=data.profile||{};googleState=data.google||googleState;applyUserProfile();loaded=true;render()}
function errorMessage(error){return error instanceof TypeError?'Não foi possível conectar. Verifique se o Studio continua aberto.':error.message||'Não foi possível concluir a operação.'}
async function mutate(path,data,message,close=true){if(busy)return false;busy=true;dialog.querySelectorAll('button').forEach(b=>b.disabled=true);const error=document.getElementById('form-error');if(error)error.hidden=true;try{await request(path,data);if(close)dialog.close();await refresh();if(!close&&modalProjectId){renderTaskList(modalProjectId);renderProduction(modalProjectId);}toast(message);if(['clients','projects','production','planning'].includes(path))scheduleGoogleSync();return true}catch(e){if(error&&dialog.open){error.textContent=errorMessage(e);error.hidden=false}else toast(errorMessage(e));return false}finally{busy=false;dialog.querySelectorAll('button').forEach(b=>b.disabled=false)}}
function modal(html){lastFocus=document.activeElement;document.getElementById('dialog-content').innerHTML=html;dialog.showModal()}
function modalHead(title){return '<div class="modal-head"><h2 id="dialog-title">'+esc(title)+'</h2><button type="button" class="icon-btn" data-close aria-label="Fechar">✕</button></div><div id="form-error" class="inline-error" role="alert" hidden></div>'}
function stats(){const ps=activeProjects().filter(p=>p.stage!=='Concluído'),due=ps.filter(p=>p.dueDate>=today()&&p.dueDate<=offsetDate(today(),6)),late=ps.filter(p=>p.dueDate<today());const values=[['folder','Projetos em andamento',ps.length,ps.filter(p=>p.stage==='Em produção').length+' em produção',''],['users','Clientes cadastrados',clients.filter(c=>!c.archived).length,'Não arquivados',''],['calendar','Entregas em 7 dias',due.length,late.length+' em atraso',late.length?'orange':''],['chart','Saldo a receber',money(activeProjects().reduce((s,p)=>s+p.valueCents-p.paidCents,0)),'Todos os projetos não arquivados','green']];return '<div class="stats">'+values.map(([i,l,v,n,c])=>'<div class="stat"><span class="stat-icon">'+icon(i)+'</span><div><label>'+l+'</label><strong>'+v+'</strong><small class="'+c+'">'+n+'</small></div></div>').join('')+'</div>'}
function card(p){const ts=projectTasks(p.id),late=p.dueDate<today()&&p.stage!=='Concluído';return '<button class="card no-cover" data-project="'+p.id+'"><div class="color-marker '+(p.service==='Social media'?'social':'')+'"></div><div class="card-service"><span class="tag">'+esc(p.service)+'</span>'+(p.archived?' <span class="status pending">Arquivado</span>':'')+'</div><h3 class="card-project-name">'+esc(p.title)+'</h3><p class="project-client">'+esc(clientName(p.clientId))+'</p><span class="date badge '+(late?'orange':'')+'">'+icon('calendar')+esc(dateLabel(p.dueDate))+(late?' · Atrasado':'')+'</span><div class="progress-row"><div class="track"><i style="width:'+progress(p)+'%"></i></div>'+progress(p)+'%</div><span class="production-card">'+productionCard(p)+'</span><span class="task-count">'+ts.filter(t=>t.done).length+'/'+ts.length+' tarefas'+(p.stage==='Concluído'?' · Projeto concluído':'')+'</span></button>'}
function filters(){return '<div class="filters" aria-label="Serviço">'+['Todos',...services].map(f=>'<button data-filter="'+f+'" class="'+(filter===f?'active':'')+'" aria-pressed="'+(filter===f)+'">'+f+'</button>').join('')+'</div>'}
function board(full=false){const ps=filtered().filter(p=>full||!p.archived);return '<section class="panel"><div class="panel-head"><h2>'+(full?'Projetos por etapa':'Fluxo de produção')+'</h2>'+filters()+'</div><div class="board" '+(full?'style="grid-template-columns:repeat(4,minmax(220px,1fr));overflow:auto"':'')+'>'+stages.slice(0,full?4:3).map((s,i)=>'<div class="column"><div class="column-head"><span class="dot '+(['','blue','yellow',''][i])+'"></span>'+s+' <small>'+ps.filter(p=>p.stage===s).length+'</small></div>'+(ps.filter(p=>p.stage===s).map(card).join('')||'<div class="empty">Nenhum projeto nesta etapa.</div>')+'</div>').join('')+'</div></section>'}
function archiveToggle(){return '<div class="toolbar"><label><input id="show-archived" type="checkbox" '+(showArchived?'checked':'')+'> Incluir arquivados</label></div>'}
function clientsTable(){return '<section class="panel"><div class="panel-head"><h2>Clientes</h2><button class="link" data-view="clients">Ver todos ↗</button></div><div class="table-wrap"><table><thead><tr><th>Cliente</th><th>Contato</th><th>Projetos ativos</th><th>Ações</th></tr></thead><tbody>'+clients.filter(c=>!c.archived).slice(0,4).map(c=>'<tr><td><div class="client-cell">'+avatar(c)+'<strong>'+esc(c.name)+'</strong></div></td><td>'+esc(c.contact||'—')+'</td><td>'+activeProjects().filter(p=>p.clientId===c.id&&p.stage!=='Concluído').length+'</td><td><button class="link" data-client="'+c.id+'">Editar ↗</button></td></tr>').join('')+'</tbody></table></div></section>'}
function event(p){return '<button class="event" style="width:100%;text-align:left" data-project="'+p.id+'"><time style="width:76px">'+esc(dateLabel(p.dueDate))+'</time><span class="dot '+(p.dueDate<today()?'':'blue')+'"></span><div><h3>'+esc(p.title)+'</h3><p>'+esc(clientName(p.clientId))+'</p></div></button>'}
function pending(){const ps=activeProjects().filter(p=>p.stage==='Em aprovação');return '<section class="panel"><div class="panel-head"><h2>Em aprovação</h2><span class="tag">'+ps.length+' projetos</span></div>'+(ps.slice(0,4).map(p=>'<button class="waiting" style="width:100%;text-align:left" data-project="'+p.id+'">'+avatar(clients.find(c=>c.id===p.clientId))+'<div><h3>'+esc(p.title)+'</h3><p>'+esc(clientName(p.clientId))+'</p><small>Entrega: '+esc(dateLabel(p.dueDate))+'</small></div></button>').join('')||'<div class="empty">Nenhum projeto aguardando aprovação.</div>')+'</section>'}
function upcoming(){const ps=activeProjects().filter(p=>p.stage!=='Concluído').sort((a,b)=>a.dueDate.localeCompare(b.dueDate));return '<section class="panel"><div class="panel-head"><h2>Próximas entregas</h2><button class="link" data-view="agenda">Ver agenda ↗</button></div>'+week()+(ps.slice(0,4).map(event).join('')||'<div class="empty">Nenhuma entrega pendente.</div>')+'</section>'}
function week(){return '<div class="week">'+Array.from({length:7},(_,i)=>{const d=offsetDate(today(),i),date=new Date(d+'T12:00:00Z');return '<button class="day '+(!i?'active':'')+'" data-day="'+d+'" aria-label="Ver entregas de '+esc(dateLabel(d))+'"><span>'+date.toLocaleDateString('pt-BR',{weekday:'short',timeZone:'America/Sao_Paulo'}).replace('.','')+'</span><strong>'+Number(d.slice(8))+'</strong></button>'}).join('')+'</div>'}
function finance(){const ps=filtered(),total=ps.reduce((s,p)=>s+p.valueCents,0),paid=ps.reduce((s,p)=>s+p.paidCents,0);return archiveToggle()+'<div class="stats">'+[['Valor contratado',total],['Total recebido',paid],['Saldo a receber',total-paid]].map(([l,n])=>'<div class="stat"><div><label>'+l+'</label><strong>'+money(n)+'</strong><small>Projetos exibidos abaixo</small></div></div>').join('')+'</div><section class="panel"><div class="panel-head"><h2>Valores por projeto</h2></div><div class="table-wrap"><table><thead><tr><th>Projeto / cliente</th><th>Contratado</th><th>Recebido</th><th>A receber</th><th>Ação</th></tr></thead><tbody>'+ps.map(p=>'<tr><td><strong>'+esc(p.title)+'</strong><br><small class="client-label">'+esc(clientName(p.clientId))+(p.archived?' · Arquivado':'')+'</small></td><td>'+money(p.valueCents)+'</td><td>'+money(p.paidCents)+'</td><td><span class="'+(p.paidCents<p.valueCents?'orange':'green')+'">'+money(p.valueCents-p.paidCents)+'</span></td><td><button class="link" data-project="'+p.id+'">Editar valores ↗</button></td></tr>').join('')+'</tbody></table></div>'+(ps.length?'':'<div class="empty">Nenhum projeto encontrado.</div>')+'<p class="help-text">Controle inicial por projeto. Parcelas, datas de pagamento e despesas ficam para uma próxima etapa.</p></section>'}
function settings(){return '<section class="panel settings-list"><div><h2>Dados locais</h2><p class="section-description">Clientes, projetos e tarefas são salvos no arquivo data/studio.sqlite.</p></div><div><h3>Backup do banco</h3><p>Baixe uma cópia consistente dos dados. Guarde também uma cópia fora deste computador.</p><div class="backup-actions"><button class="primary" id="backup">Baixar backup</button></div><p class="help-text">Uma cópia também é guardada em data/backups. A restauração é feita com o Studio fechado; consulte o LEIA-ME.</p></div><div><h3>Google Agenda e Forms</h3><p>Conecte sua conta e acompanhe a configuração em Perfil e integrações.</p><button class="secondary" data-user-settings>Perfil e integrações</button></div><div><h3>Dados de exemplo</h3><p>'+(clients.length?'A base já possui clientes. Os exemplos só podem ser carregados em uma base vazia.':'Você pode explorar os recursos com três clientes e três projetos de exemplo.')+'</p>'+(!clients.length?'<div class="backup-actions"><button class="secondary" data-demo>Carregar exemplos</button></div>':'')+'</div></section>'}
function render(){document.getElementById('nav').innerHTML=Object.entries(labels).filter(([v])=>v!=='account').map(([v,l],i)=>'<button data-view="'+v+'" class="'+(view===v?'active':'')+'" '+(view===v?'aria-current="page"':'')+'>'+icon(({overview:'home',projects:'folder',clients:'users',agenda:'calendar',planning:'calendar',finance:'chart',settings:'folder'})[v])+l+'</button>').join('');document.getElementById('crumb').textContent=labels[view];document.getElementById('title').textContent=labels[view];document.getElementById('subtitle').textContent={overview:new Date().toLocaleDateString('pt-BR',{dateStyle:'full',timeZone:'America/Sao_Paulo'}),projects:'Trabalhos organizados por etapa.',clients:'Cadastro, contatos e projetos por cliente.',agenda:'Prazos dos projetos em andamento.',planning:'Conteúdos da semana, revisão e aprovação por cliente.',finance:'Valores contratados e recebidos por projeto.',settings:'Armazenamento e cópias de segurança.',account:'Seu perfil, preferências e conexão com o Google.'}[view];const primary=document.getElementById('new-project');primary.hidden=['settings','account'].includes(view);primary.style.display=['settings','account'].includes(view)?'none':'';primary.innerHTML=icon('plus')+(view==='clients'?'Novo cliente':view==='planning'?'Novo planejamento':'Novo projeto');primary.disabled=!loaded;let out='';if(view==='overview'){out=stats();if(!clients.length)out+='<section class="panel empty-state"><h2>Nenhum cliente cadastrado</h2><p>Cadastre o primeiro cliente para começar a organizar os projetos.</p><button class="primary" data-new-client>Adicionar cliente</button><button class="secondary" data-demo>Explorar com exemplos</button></section>';else out+='<div class="dashboard-grid"><div>'+board()+clientsTable()+'</div><div class="right-column">'+upcoming()+pending()+'</div></div>'}if(view==='projects')out=archiveToggle()+board(true);if(view==='clients'){const cs=clients.filter(c=>(showArchived||!c.archived)&&(c.name+' '+c.contact+' '+c.email).toLowerCase().includes(query.toLowerCase()));out=archiveToggle()+'<div class="client-grid">'+cs.map(c=>'<article class="panel client-tile">'+avatar(c)+'<h2>'+esc(c.name)+'</h2><p>'+esc(c.contact||'Contato não informado')+(c.email?'<br>'+esc(c.email):'')+(c.phone?'<br>'+esc(c.phone):'')+'</p><footer><span>'+activeProjects().filter(p=>p.clientId===c.id&&p.stage!=='Concluído').length+' projetos ativos</span><span class="status '+(c.archived?'pending':'')+'">'+(c.archived?'Arquivado':'Ativo')+'</span></footer><div class="table-actions" style="margin-top:18px"><button class="link" data-client="'+c.id+'">Editar cliente ↗</button><button class="link" data-client-projects="'+c.id+'">Ver projetos ↗</button></div></article>').join('')+'</div>';if(!cs.length)out+='<section class="panel empty">Nenhum cliente encontrado. Use “Novo cliente” para cadastrar.</section>'}if(view==='agenda'){const ps=filtered().filter(p=>p.stage!=='Concluído').sort((a,b)=>a.dueDate.localeCompare(b.dueDate));out='<section class="panel agenda-list"><div class="panel-head"><h2>Entregas pendentes</h2><span class="tag">'+ps.length+' projetos</span></div>'+week()+'<div id="agenda-events">'+(ps.map(event).join('')||'<div class="empty">Nenhuma entrega encontrada.</div>')+'</div></section>'}if(view==='planning')out=planningView();if(view==='finance')out=finance();if(view==='settings')out=settings();if(view==='account')out=accountView();if(view==='agenda')out=googleAgendaPanel()+out;content.innerHTML=out;document.getElementById('search').placeholder=view==='clients'?'Buscar clientes':view==='planning'?'Buscar conteúdos':'Buscar projetos ou clientes';document.getElementById('search').disabled=['settings','account'].includes(view)}
function openClient(cid){const c=clients.find(c=>c.id===cid);modalProjectId=null;modal(modalHead(c?'Editar cliente':'Novo cliente')+'<form id="client-form"><label for="client-name">Nome do cliente ou empresa *</label><input id="client-name" name="name" required maxlength="120" value="'+esc(c?.name||'')+'" placeholder="Ex.: Empresa Silva"><label for="client-contact">Nome do contato</label><input id="client-contact" name="contact" maxlength="120" value="'+esc(c?.contact||'')+'"><div class="form-grid"><div><label for="client-email">E-mail</label><input id="client-email" name="email" type="email" maxlength="180" value="'+esc(c?.email||'')+'"></div><div><label for="client-phone">Telefone</label><input id="client-phone" name="phone" type="tel" maxlength="40" value="'+esc(c?.phone||'')+'"></div></div><label for="client-notes">Observações</label><textarea id="client-notes" name="notes" maxlength="4000">'+esc(c?.notes||'')+'</textarea><div class="modal-actions">'+(c?'<button type="button" class="secondary" id="archive-client">'+(c.archived?'Restaurar cliente':'Arquivar cliente')+'</button>':'')+'<button type="button" class="secondary" data-close>Cancelar</button><button class="primary" type="submit">'+(c?'Salvar alterações':'Adicionar cliente')+'</button></div></form>');document.getElementById('client-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);mutate('clients',{...(c?{id:c.id}:{}),name:f.get('name'),contact:f.get('contact'),email:f.get('email'),phone:f.get('phone'),notes:f.get('notes'),archived:c?.archived||false},c?'Cliente atualizado.':'Cliente adicionado.')};if(c)document.getElementById('archive-client').onclick=()=>mutate('clients',{...c,archived:!c.archived},c.archived?'Cliente restaurado.':'Cliente arquivado.')}
function openProject(pid){const p=projects.find(p=>p.id===pid);if(!p&&!clients.some(c=>!c.archived)){toast('Cadastre um cliente antes de criar um projeto.');openClient();return}modalProjectId=p?.id||null;const options=clients.filter(c=>!c.archived||c.id===p?.clientId);modal(modalHead(p?'Editar projeto':'Novo projeto')+'<form id="project-form" class="project-form"><label for="project-title">Nome do projeto *</label><input id="project-title" name="title" required maxlength="120" value="'+esc(p?.title||'')+'" placeholder="Ex.: Reels de lançamento"><div class="form-grid"><div><label for="project-client">Cliente *</label><select id="project-client" name="clientId" required>'+options.map(c=>'<option value="'+c.id+'" '+(p?.clientId===c.id?'selected':'')+'>'+esc(c.name)+(c.archived?' (arquivado)':'')+'</option>').join('')+'</select></div><div><label for="project-service">Serviço</label><select id="project-service" name="service">'+services.map(s=>'<option '+(p?.service===s?'selected':'')+'>'+s+'</option>').join('')+'</select></div></div><div class="form-grid"><div><label for="project-date">Data de entrega *</label><input id="project-date" name="dueDate" type="date" required min="1900-01-01" max="9999-12-31" value="'+esc(p?.dueDate||today())+'"></div><div><label for="project-stage">Etapa</label><select id="project-stage" name="stage">'+stages.map(s=>'<option '+(p?.stage===s?'selected':'')+'>'+s+'</option>').join('')+'</select></div></div><div class="form-grid"><div><label for="project-value">Valor contratado (R$)</label><input id="project-value" name="value" type="number" required min="0" max="10000000" step="0.01" value="'+((p?.valueCents||0)/100).toFixed(2)+'"></div><div><label for="project-paid">Total recebido (R$)</label><input id="project-paid" name="paid" type="number" required min="0" max="10000000" step="0.01" value="'+((p?.paidCents||0)/100).toFixed(2)+'"></div></div><label for="project-notes">Briefing</label><textarea id="project-notes" name="notes" maxlength="4000">'+esc(p?.notes||'')+'</textarea><div class="modal-actions">'+(p?'<button type="button" class="secondary" id="archive-project">'+(p.archived?'Restaurar projeto':'Arquivar projeto')+'</button>':'')+'<button type="button" class="secondary" data-close>Cancelar</button><button type="submit" class="primary">'+(p?'Salvar alterações':'Criar projeto')+'</button></div></form>'+(p?'<div id="project-production"></div><div class="task-heading"><h3>Tarefas</h3><span id="task-summary"></span></div><div id="project-tasks"></div>'+(!p.archived?'<form id="task-form" class="task-add"><input name="title" required maxlength="120" aria-label="Nome da nova tarefa" placeholder="Adicionar tarefa"><button type="submit" class="secondary">Adicionar</button></form>':'<p class="help-text">Restaure o projeto para alterar as tarefas.</p>')+'<p class="help-text">O progresso acompanha as tarefas. Ao marcar o projeto como concluído, o painel exibe 100% sem modificar a lista.</p>':'<p class="help-text">As tarefas podem ser adicionadas depois de criar o projeto.</p>'));document.getElementById('project-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);mutate('projects',{...(p?{id:p.id}:{}),clientId:Number(f.get('clientId')),title:f.get('title'),service:f.get('service'),stage:f.get('stage'),dueDate:f.get('dueDate'),valueCents:Math.round(Number(f.get('value'))*100),paidCents:Math.round(Number(f.get('paid'))*100),notes:f.get('notes'),archived:p?.archived||false},p?'Projeto atualizado.':'Projeto criado.')};if(p){renderTaskList(p.id);renderProduction(p.id);document.getElementById('archive-project').onclick=()=>{const latest=projects.find(project=>project.id===p.id);mutate('projects',{...latest,archived:!latest.archived},latest.archived?'Projeto restaurado.':'Projeto arquivado.')};const form=document.getElementById('task-form');if(form)form.onsubmit=async e=>{e.preventDefault();const f=new FormData(form);if(await mutate('tasks',{action:'create',projectId:p.id,title:f.get('title')},'Tarefa adicionada.',false))form.reset()}}}
function renderTaskList(pid){const p=projects.find(p=>p.id===pid);if(!p)return;const ts=projectTasks(pid);document.getElementById('task-summary').textContent=ts.filter(t=>t.done).length+'/'+ts.length+' concluídas';document.getElementById('project-tasks').innerHTML='<ul class="task-list">'+ts.map(t=>'<li><label class="'+(t.done?'done':'')+'"><input type="checkbox" data-task="'+t.id+'" '+(t.done?'checked':'')+' '+(p.archived?'disabled':'')+'>'+esc(t.title)+'</label>'+(!p.archived?'<button type="button" class="link danger-text" data-delete-task="'+t.id+'" aria-label="Excluir tarefa '+esc(t.title)+'">Excluir</button>':'')+'</li>').join('')+'</ul>'+(!ts.length?'<p class="help-text">Nenhuma tarefa cadastrada.</p>':'')}
async function backup(){const b=document.getElementById('backup');if(b)b.disabled=true;try{const res=await fetch('/api/backup',{method:'POST'});if(!res.ok){const err=await res.json();throw new Error(err.error)}const blob=await res.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=res.headers.get('content-disposition')?.match(/filename="([^"]+)"/)?.[1]||'studio-backup.sqlite';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup gerado. Uma cópia também foi salva em data/backups.')}catch(e){toast(errorMessage(e))}finally{if(b)b.disabled=false}}
