document.addEventListener('change',e=>{if(e.target.id==='show-archived'){showArchived=e.target.checked;render()}if(e.target.dataset.task){const input=e.target;mutate('tasks',{action:'toggle',id:Number(input.dataset.task),done:input.checked},'Tarefa atualizada.',false).then(ok=>{if(!ok)input.checked=!input.checked})}});
document.getElementById('search').oninput=e=>{query=e.target.value;render()};document.getElementById('new-project').onclick=()=>view==='clients'?openClient():view==='planning'?openPlan():openProject();document.getElementById('notifications').innerHTML=icon('bell');document.getElementById('notifications').onclick=()=>{navigate('agenda');const late=activeProjects().filter(p=>p.stage!=='Concluído'&&p.dueDate<today()).length;toast(late?late+' projeto(s) com entrega atrasada.':'Nenhuma entrega atrasada.')};document.getElementById('search-icon').innerHTML=icon('search');document.getElementById('menu').onclick=()=>document.getElementById('sidebar').classList.toggle('open');document.getElementById('close-menu').onclick=()=>document.getElementById('sidebar').classList.remove('open');dialog.addEventListener('cancel',e=>{if(busy)e.preventDefault()});dialog.addEventListener('close',()=>{modalProjectId=null;lastFocus?.focus()});dialog.addEventListener('click',e=>{if(e.target===dialog&&!busy){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
