const approvalLabels={rascunho:'Rascunho',pendente:'Aguardando aprovação',aprovado:'Aprovado',ajustes:'Ajustes solicitados'};
function checkedProduction(pid){return productionStates.filter(s=>s.projectId===pid&&s.done).map(s=>s.step)}
function productionCard(p){const checked=checkedProduction(p.id),next=productionLabels.find(s=>!checked.includes(s));return '<span class="process-caption">Processo · '+checked.length+'/7</span><span class="process-next">'+esc(checked.length?next||'Produção finalizada':'Checklist ainda não iniciado')+'</span><span class="publication-badge '+(p.published?'is-posted':'')+'">'+(p.published?'● Postado':'○ Não postado')+'</span>'}
function renderProduction(pid){const p=projects.find(p=>p.id===pid),host=document.getElementById('project-production');if(!p||!host)return;const checked=checkedProduction(pid);host.innerHTML='<section class="production-section"><div class="task-heading"><h3>Processo de produção</h3><span>'+checked.length+' de 7 etapas</span></div><ol class="production-checklist">'+productionLabels.map((label,i)=>'<li><label><input type="checkbox" data-production-step="'+esc(label)+'" data-production-id="'+pid+'" '+(checked.includes(label)?'checked ':'')+(p.archived?'disabled':'')+'><span class="step-number">'+String(i+1).padStart(2,'0')+'</span><span>'+esc(label)+'</span></label></li>').join('')+'</ol><p class="help-text">As etapas são salvas ao marcar. A etapa geral do quadro acompanha a primeira pendência. As tarefas abaixo continuam independentes.</p><form id="publication-form" data-production-id="'+pid+'"><div class="publication-heading"><h3>Publicação</h3><span class="publication-badge '+(p.published?'is-posted':'')+'">'+(p.published?'Postado':'Não postado')+'</span></div><label class="check-label"><input id="publication-posted" type="checkbox" '+(p.published?'checked ':'')+(p.archived?'disabled':'')+'> Já foi postado</label><div class="form-grid"><div><label for="publication-date">Data da publicação</label><input id="publication-date" type="date" min="1900-01-01" max="9999-12-31" value="'+esc(p.publishedDate||'')+'" '+(p.archived?'disabled':'')+'></div><div><label for="publication-url">Link da publicação</label><input id="publication-url" type="url" maxlength="2000" placeholder="https://…" value="'+esc(p.publishedUrl||'')+'" '+(p.archived?'disabled':'')+'></div></div><p class="help-text">Finalize o projeto para marcar como postado. Este controle registra a publicação já feita.</p>'+(!p.archived?'<button type="submit" class="secondary">Salvar publicação</button>':'')+'</form></section>';const stage=document.getElementById('project-stage');if(stage)stage.value=p.stage;}
function monday(day){const d=new Date(day+'T12:00:00Z');d.setUTCDate(d.getUTCDate()-((d.getUTCDay()+6)%7));return d.toISOString().slice(0,10)}
function currentPlan(){return plans.find(p=>p.id===Number(selectedPlanId))||null}
function planningView(){if(!plans.length)return '<section class="panel empty-state"><p class="eyebrow">PLANEJAMENTO SEMANAL</p><h2>A próxima semana começa aqui</h2><p>Organize os conteúdos de um cliente e prepare a apresentação para aprovação.</p><button class="primary" data-new-plan>Criar planejamento</button></section>';if(!currentPlan())selectedPlanId=plans[0].id;const plan=currentPlan(),items=planItems.filter(i=>i.planId===plan.id),visible=items.filter(i=>(i.title+' '+i.caption+' '+i.channel).toLocaleLowerCase('pt-BR').includes(query.toLocaleLowerCase('pt-BR'))),archived=clients.find(c=>c.id===plan.clientId)?.archived;return '<div class="planning-toolbar"><label for="plan-selector">Cliente / semana<select id="plan-selector">'+plans.map(p=>'<option value="'+p.id+'" '+(p.id===plan.id?'selected':'')+'>'+esc(clientName(p.clientId))+' · '+esc(dateLabel(p.weekStart))+' · '+esc(p.title)+'</option>').join('')+'</select></label><div class="planning-actions"><button class="secondary" data-edit-plan="'+plan.id+'" '+(archived?'disabled':'')+'>Editar planejamento</button><button class="primary" data-new-content '+(archived?'disabled':'')+'>Adicionar conteúdo</button></div></div><section class="panel planning-intro"><div><p class="eyebrow">'+esc(clientName(plan.clientId))+' / SEMANA '+esc(plan.weekStart.split('-').reverse().join('/'))+'</p><h2>'+esc(plan.title)+'</h2><p class="plan-instructions">'+esc(plan.instructions||'Adicione os conteúdos e prepare o envio para o cliente revisar.')+'</p></div><div class="approval-summary">'+Object.entries(approvalLabels).map(([key,label])=>'<span class="approval-count '+key+'"><strong>'+items.filter(i=>i.status===key).length+'</strong>'+label+'</span>').join('')+'</div>'+planningGoogleControls(plan,items,archived)+'<p id="planning-error" class="inline-error" role="alert" hidden></p>'+(archived?'<p class="help-text">Cliente arquivado. Restaure o cliente para editar ou enviar este planejamento.</p>':'')+'</section><p class="help-text planning-scroll-hint">Deslize a semana para ver os outros dias.</p><div class="planning-week">'+Array.from({length:7},(_,day)=>{const date=offsetDate(plan.weekStart,day),dayItems=visible.filter(i=>i.publishDate===date);return '<section class="planning-day"><header><span>'+new Date(date+'T12:00:00Z').toLocaleDateString('pt-BR',{weekday:'short',timeZone:'America/Sao_Paulo'}).replace('.','')+'</span><strong>'+date.slice(8)+'</strong><small>'+dayItems.length+' conteúdo'+(dayItems.length===1?'':'s')+'</small></header>'+dayItems.map(planningCard).join('')+(!dayItems.length?'<p class="day-empty">'+(query?'Sem resultados':'Sem conteúdo')+'</p>':'')+(!archived?'<button class="day-add" data-add-content-day="'+date+'" aria-label="Adicionar conteúdo em '+esc(dateLabel(date))+'">+ Adicionar</button>':'')+'</section>'}).join('')+'</div>';}
function planningCard(item){return '<button class="content-card" data-plan-item="'+item.id+'">'+(item.thumbnail?'<img src="'+esc(item.thumbnail)+'" alt="Miniatura de '+esc(item.title)+'" loading="lazy">':'<span class="thumbnail-placeholder">'+esc(item.format)+'</span>')+'<span class="content-card-body"><span class="content-meta">'+esc(item.channel)+' · '+esc(item.format)+'</span><strong>'+esc(item.title)+'</strong><span class="approval-status '+item.status+'">'+approvalLabels[item.status]+'</span>'+(item.feedback?'<span class="content-feedback">'+esc(item.feedback)+'</span>':'')+'<small>Versão '+item.revision+(item.projectId?' · Projeto vinculado':'')+'</small></span></button>';}
function openPlan(pid){if(!clients.some(c=>!c.archived)){toast('Cadastre um cliente antes de criar um planejamento.');openClient();return}modalProjectId=null;const plan=plans.find(p=>p.id===pid),hasItems=plan&&planItems.some(i=>i.planId===pid);modal(modalHead(plan?'Editar planejamento':'Novo planejamento')+'<form id="plan-form"><label for="plan-client">Cliente *</label><select id="plan-client" required '+(hasItems?'disabled':'')+'>'+clients.filter(c=>!c.archived||c.id===plan?.clientId).map(c=>'<option value="'+c.id+'" '+(c.id===plan?.clientId?'selected':'')+'>'+esc(c.name)+'</option>').join('')+'</select><label for="plan-week">Semana de publicação *</label><input id="plan-week" type="date" required min="1900-01-01" max="9999-12-25" value="'+esc(plan?.weekStart||monday(today()))+'" '+(hasItems?'disabled':'')+'><p class="help-text">Escolha um dia; a semana será organizada de segunda a domingo.'+(hasItems?' Cliente e semana ficam fixos após adicionar conteúdos.':'')+'</p><label for="plan-title">Título *</label><input id="plan-title" required maxlength="120" value="'+esc(plan?.title||'Conteúdos da semana')+'"><label for="plan-instructions">Orientação para o cliente</label><textarea id="plan-instructions" maxlength="4000" placeholder="O que o cliente deve considerar na revisão?">'+esc(plan?.instructions||'')+'</textarea><div class="modal-actions"><button type="button" class="secondary" data-close>Cancelar</button><button class="primary" type="submit">Salvar planejamento</button></div></form>');document.getElementById('plan-form').onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;const error=document.getElementById('form-error'),button=e.target.querySelector('[type=submit]');button.disabled=true;try{const result=await request('planning',{action:'savePlan',...(plan?{id:plan.id}:{}),clientId:Number(document.getElementById('plan-client').value),weekStart:monday(document.getElementById('plan-week').value),title:document.getElementById('plan-title').value,instructions:document.getElementById('plan-instructions').value});selectedPlanId=result.id;dialog.close();await refresh();toast('Planejamento salvo.');scheduleGoogleSync()}catch(err){error.textContent=errorMessage(err);error.hidden=false}finally{busy=false;button.disabled=false}};}
async function resizeThumbnail(file){if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>10*1024*1024)throw new Error('Escolha uma imagem PNG, JPEG ou WebP de até 10 MB.');const bitmap=await createImageBitmap(file);try{const scale=Math.min(1,900/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#ffffff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);let result=canvas.toDataURL('image/jpeg',.82);if(result.length>470000)result=canvas.toDataURL('image/jpeg',.55);if(result.length>470000)throw new Error('A imagem ficou muito grande. Escolha uma miniatura menor.');return result;}finally{bitmap.close()}}
function openContent(iid,day){const plan=currentPlan();if(!plan)return;modalProjectId=null;const item=planItems.find(i=>i.id===iid),archived=clients.find(c=>c.id===plan.clientId)?.archived;let thumbnail=item?.thumbnail||'',processing=false;const choices=projects.filter(p=>p.clientId===plan.clientId&&(!p.archived||p.id===item?.projectId));modal(modalHead(item?'Editar conteúdo':'Novo conteúdo')+'<form id="content-form"><label for="content-title">Título *</label><input id="content-title" required maxlength="120" value="'+esc(item?.title||'')+'"><div class="form-grid"><div><label for="content-date">Data de publicação *</label><input id="content-date" type="date" required min="'+plan.weekStart+'" max="'+offsetDate(plan.weekStart,6)+'" value="'+esc(item?.publishDate||day||plan.weekStart)+'"></div><div><label for="content-channel">Canal</label><select id="content-channel">'+contentChannels.map(c=>'<option '+(c===item?.channel?'selected':'')+'>'+c+'</option>').join('')+'</select></div></div><div class="form-grid"><div><label for="content-format">Formato</label><select id="content-format">'+contentFormats.map(c=>'<option '+(c===item?.format?'selected':'')+'>'+c+'</option>').join('')+'</select></div><div><label for="content-project">Projeto vinculado (opcional)</label><select id="content-project"><option value="">Sem vínculo</option>'+choices.map(p=>'<option value="'+p.id+'" '+(p.id===item?.projectId?'selected':'')+'>'+esc(p.title)+(p.archived?' (arquivado)':'')+'</option>').join('')+'</select></div></div><label for="content-caption">Legenda / descrição</label><textarea id="content-caption" maxlength="8000">'+esc(item?.caption||'')+'</textarea><label for="content-thumbnail">Miniatura</label><input id="content-thumbnail" type="file" accept="image/png,image/jpeg,image/webp"><div id="thumbnail-preview" class="thumbnail-preview">'+(thumbnail?'<img src="'+esc(thumbnail)+'" alt="Prévia da miniatura">':'')+'</div><button type="button" class="link" id="clear-thumbnail">Remover miniatura</button><label for="content-url">Link do material (opcional)</label><input id="content-url" type="url" maxlength="2000" value="'+esc(item?.materialUrl||'')+'" placeholder="https://…">'+(item?'<div class="review-feedback"><span class="approval-status '+item.status+'">'+approvalLabels[item.status]+'</span><p>'+esc(item.feedback||'Nenhum comentário recebido.')+'</p>'+(item.reviewer?'<small>'+esc(item.reviewer)+' · '+esc(new Date(item.reviewedAt).toLocaleString('pt-BR'))+'</small>':'')+'<p class="help-text">Alterar o conteúdo cria uma nova versão e pede uma nova aprovação.</p></div>':'')+'<div class="modal-actions">'+(item&&!archived?'<button type="button" class="link danger-text" id="delete-content">Excluir conteúdo</button>':'')+'<button type="button" class="secondary" data-close>Fechar</button>'+(!archived?'<button class="primary" type="submit">Salvar conteúdo</button>':'')+'</div></form>');const form=document.getElementById('content-form');if(archived){form.querySelectorAll('input,select,textarea,#clear-thumbnail').forEach(el=>el.disabled=true);return}const preview=document.getElementById('thumbnail-preview'),save=form.querySelector('[type=submit]'),error=document.getElementById('form-error');document.getElementById('content-thumbnail').onchange=async e=>{if(!e.target.files[0])return;processing=true;save.disabled=true;try{thumbnail=await resizeThumbnail(e.target.files[0]);preview.innerHTML='<img src="'+thumbnail+'" alt="Prévia da miniatura">';error.hidden=true;}catch(err){error.textContent=errorMessage(err);error.hidden=false;}finally{processing=false;save.disabled=false}};document.getElementById('clear-thumbnail').onclick=()=>{if(processing)return;thumbnail='';preview.innerHTML='';document.getElementById('content-thumbnail').value=''};form.onsubmit=e=>{e.preventDefault();if(processing)return;mutate('planning',{action:'saveItem',planId:plan.id,...(item?{id:item.id}:{}),title:document.getElementById('content-title').value,publishDate:document.getElementById('content-date').value,format:document.getElementById('content-format').value,channel:document.getElementById('content-channel').value,projectId:Number(document.getElementById('content-project').value)||null,caption:document.getElementById('content-caption').value,materialUrl:document.getElementById('content-url').value,thumbnail},'Conteúdo salvo.')};if(item)document.getElementById('delete-content').onclick=()=>{if(confirm('Excluir “'+item.title+'” do planejamento?'))mutate('planning',{action:'deleteItem',id:item.id},'Conteúdo excluído.')};}
function downloadFile(body,type,name){const blob=new Blob([body],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function planningError(error){const host=document.getElementById('planning-error');if(host){host.textContent=errorMessage(error);host.hidden=false}else toast(errorMessage(error))}
async function exportPlan(){if(busy||!currentPlan())return;busy=true;const plan=currentPlan(),button=document.getElementById('export-plan');button.disabled=true;try{const result=await request('planning',{action:'export',planId:plan.id});downloadFile(result.html,'text/html;charset=utf-8','planejamento-'+plan.weekStart+'-'+plan.id+'.html');await refresh();toast('Arquivo preparado. Envie ao cliente para aprovação.')}catch(err){planningError(err)}finally{busy=false;if(button.isConnected)button.disabled=false}}
async function importApproval(file){if(busy||!file||!currentPlan())return;busy=true;const planId=currentPlan().id;try{if(file.size>512*1024)throw new Error('O arquivo de respostas é muito grande. Escolha o JSON baixado pelo cliente.');let response;try{response=JSON.parse(await file.text())}catch{throw new Error('Arquivo inválido. Escolha o JSON de respostas do cliente.')}const result=await request('planning',{action:'import',planId,response});await refresh();toast(result.count+' resposta(s) importada(s).')}catch(err){planningError(err)}finally{busy=false;const field=document.getElementById('import-approval');if(field)field.value=''}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-new-plan'))openPlan();if(b.dataset.editPlan)openPlan(Number(b.dataset.editPlan));if(b.hasAttribute('data-new-content'))openContent();if(b.dataset.addContentDay)openContent(undefined,b.dataset.addContentDay);if(b.dataset.planItem)openContent(Number(b.dataset.planItem));if(b.id==='export-plan')exportPlan()});
document.addEventListener('change',async e=>{if(e.target.id==='plan-selector'){selectedPlanId=Number(e.target.value);render()}if(e.target.id==='import-approval')importApproval(e.target.files[0]);if(e.target.dataset.productionStep){const target=e.target,pid=Number(target.dataset.productionId);target.disabled=true;await mutate('production',{action:'step',projectId:pid,step:target.dataset.productionStep,done:target.checked},'Etapa atualizada.',false);renderProduction(pid)}});
document.addEventListener('submit',async e=>{if(e.target.id!=='publication-form')return;e.preventDefault();const pid=Number(e.target.dataset.productionId);await mutate('production',{action:'publish',projectId:pid,published:document.getElementById('publication-posted').checked,publishedDate:document.getElementById('publication-date').value,publishedUrl:document.getElementById('publication-url').value},'Publicação atualizada.',false);renderProduction(pid)});

let googleSyncTimer,googleWorking=false;
function applyUserProfile(){const name=userProfile.name||'Usuário local',initials=name.trim().split(/\s+/).slice(0,2).map(s=>s[0]).join('').toUpperCase();document.querySelectorAll('[data-profile-name]').forEach(el=>el.textContent=name);document.querySelectorAll('[data-profile-role]').forEach(el=>el.textContent=userProfile.role||'Neste computador');document.querySelectorAll('[data-studio-name]').forEach(el=>el.textContent=userProfile.studioName||'Meu estúdio');document.querySelectorAll('.profile .avatar,.user-avatar-button').forEach(el=>el.textContent=initials);document.documentElement.style.setProperty('--lime',({lime:'#d1ff5e',purple:'#c4afff',blue:'#8dcaff'})[userProfile.accent]||'#d1ff5e');document.body.classList.toggle('compact-density',userProfile.density==='compact');}
function googleConnected(){return googleState.connected&&!googleState.reconnectRequired&&!googleState.credentialError}
function formatSync(date){return date?new Date(date).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'}):'Ainda não sincronizado'}
function googleSetupSteps(){return '<ol class="setup-steps"><li><strong>Crie o projeto Google Cloud</strong><p>Entre com a conta Gmail que será dona da agenda e dos formulários. Crie um projeto chamado Studio.</p><a href="https://console.cloud.google.com/projectcreate" target="_blank" rel="noopener noreferrer">Abrir Google Cloud ↗</a></li><li><strong>Ative três APIs</strong><p>Em APIs e serviços → Biblioteca, ative Google Calendar API, Google Forms API e Google Drive API. O Drive é usado para os formulários e, se você habilitar, para suas miniaturas.</p><a href="https://console.cloud.google.com/apis/library" target="_blank" rel="noopener noreferrer">Abrir Biblioteca ↗</a></li><li><strong>Configure o consentimento</strong><p>Em Google Auth Platform, preencha Branding com nome do app e seus e-mails. Em Audience, escolha Externo e adicione seu próprio Gmail como usuário de teste. Em Data Access, adicione os escopos descritos no guia completo.</p><p class="help-text">No modo de teste, a autorização pode expirar em 7 dias. Isso é uma regra do Google; reconecte quando solicitado. Para uso contínuo, revise a publicação e a verificação do aplicativo.</p></li><li><strong>Crie o cliente OAuth</strong><p>Em Clients → Create client, escolha Aplicativo da Web. Em URIs de redirecionamento autorizados, adicione exatamente:</p>'+ (googleState.redirectUris||[]).map(uri=>'<code class="redirect-uri">'+esc(uri)+'</code>').join('')+'<p>Baixe o JSON das credenciais. Guarde-o em local privado.</p></li><li><strong>Importe e conecte</strong><p>Importe o JSON no formulário desta tela, clique Salvar credenciais e depois Conectar Google. Na autorização, permita as permissões solicitadas de Agenda, Forms, respostas e arquivos do Studio.</p></li><li><strong>Faça a primeira sincronização</strong><p>Na aba Agenda, clique Sincronizar Google Agenda. No planejamento, clique Gerar link Google Forms. Teste o link no navegador anônimo ou em outro celular antes de enviar ao cliente.</p></li></ol>';}
function accountView(){const p=userProfile,connected=googleConnected();return '<div class="account-grid"><section class="panel"><div class="panel-head"><h2>Meu perfil</h2><span class="tag">Neste computador</span></div><form id="profile-form"><label for="profile-name">Seu nome *</label><input id="profile-name" required maxlength="120" value="'+esc(p.name||'')+'"><label for="profile-studio">Nome do estúdio *</label><input id="profile-studio" required maxlength="120" value="'+esc(p.studioName||'')+'"><label for="profile-role">Função</label><input id="profile-role" maxlength="120" value="'+esc(p.role||'')+'"><label for="profile-email">E-mail de contato</label><input id="profile-email" type="email" maxlength="180" value="'+esc(p.email||'')+'"><div class="form-grid"><div><label for="profile-accent">Cor de destaque</label><select id="profile-accent">'+[['lime','Verde'],['purple','Lilás'],['blue','Azul']].map(([v,l])=>'<option value="'+v+'" '+(v===p.accent?'selected':'')+'>'+l+'</option>').join('')+'</select></div><div><label for="profile-density">Espaçamento</label><select id="profile-density"><option value="comfortable" '+(p.density!=='compact'?'selected':'')+'>Confortável</option><option value="compact" '+(p.density==='compact'?'selected':'')+'>Compacto</option></select></div></div><label class="check-label"><input id="profile-auto-sync" type="checkbox" '+(p.autoGoogleSync?'checked':'')+'> Sincronizar Google automaticamente com o Studio aberto</label><label class="check-label"><input id="profile-form-images" type="checkbox" '+(p.formsUploadImages?'checked':'')+'> Incluir miniaturas nos formulários</label><p class="help-text">Ao gerar um formulário com imagens, as miniaturas serão enviadas ao seu Drive e disponibilizadas por link para o Google Forms. Sem essa opção, o formulário terá os textos e links dos materiais.</p><p id="profile-error" class="inline-error" role="alert" hidden></p><button class="primary" type="submit">Salvar perfil e preferências</button></form></section><section class="panel"><div class="panel-head"><h2>Conexão Google</h2><span class="approval-status '+(connected?'aprovado':'pendente')+'">'+(connected?'Conectado':googleState.reconnectRequired?'Reconectar':googleState.configured?'Pronto para conectar':'Configuração necessária')+'</span></div><p class="connection-account">'+esc(connected?googleState.email:'Use a conta Google do estúdio para Agenda e Forms.')+'</p><form id="google-credentials-form"><label for="google-credentials-file">Importar credenciais OAuth (JSON)</label><input id="google-credentials-file" type="file" accept=".json,application/json"><p class="help-text">Arquivo baixado em Google Cloud → Google Auth Platform → Clients. Escolha credenciais do tipo Aplicativo da Web.</p><label for="google-client-id">Client ID</label><input id="google-client-id" autocomplete="off" spellcheck="false" maxlength="512" value="'+esc(googleState.clientId||'')+'" placeholder="…apps.googleusercontent.com"><label for="google-client-secret">Client secret</label><input id="google-client-secret" type="password" autocomplete="new-password" maxlength="512" placeholder="'+(googleState.configured?'Já salvo; deixe vazio para manter':'Cole o segredo baixado do Google Cloud')+'"><p class="help-text">O segredo e os tokens são criptografados no servidor. Eles não são exibidos novamente.</p><button class="secondary" type="submit">Salvar credenciais</button></form><div class="google-actions"><button class="primary" id="google-connect" '+(!googleState.configured?'disabled':'')+'>'+(googleState.connected?'Reconectar Google':'Conectar Google')+'</button>'+(googleState.connected?'<button class="secondary" id="google-disconnect">Desconectar</button>':'')+'</div><p class="help-text">Desconectar não exclui a agenda, os eventos ou os formulários já criados. Links de formulários continuam ativos até serem encerrados.</p><p id="google-error" class="inline-error" role="alert" '+(!(googleState.lastError||googleState.credentialError)?'hidden':'')+'>'+esc(googleState.credentialError||googleState.lastError||'')+'</p><dl class="sync-summary"><div><dt>Agenda</dt><dd>'+esc(formatSync(googleState.calendarLastSync))+'</dd></div><div><dt>Aprovações</dt><dd>'+esc(formatSync(googleState.formsLastSync))+'</dd></div><div><dt>Fuso</dt><dd>America/Sao_Paulo</dd></div></dl></section></div><section class="panel google-guide"><div class="panel-head"><div><p class="eyebrow">CONFIGURAÇÃO INICIAL</p><h2>Como liberar Google Agenda e Forms</h2></div><a class="secondary" href="/guia-configuracao-google.html" download>Baixar guia completo</a></div>'+googleSetupSteps()+'<a class="secondary client-guide-download" href="/guia-aprovacao-cliente.html" download>Baixar guia para enviar ao cliente</a><p class="help-text">Este perfil é uma preferência local, não um login com senha. As integrações reais funcionam na aplicação Next.js; o HTML estático continua independente.</p></section>';}
function googleAgendaPanel(){const connected=googleConnected(),links=googleState.calendarLinks||[],conflicts=links.filter(l=>l.status==='conflito'),errors=links.filter(l=>l.status==='erro');return '<section class="panel google-agenda-panel"><div><h2>Google Agenda</h2><p>'+esc(connected?'Prazos enviados para o calendário Studio · '+googleState.email:'Conecte sua conta para enviar os prazos dos projetos.')+'</p><small>'+esc(formatSync(googleState.calendarLastSync))+'</small></div><div class="google-actions">'+(connected?'<button class="secondary" id="google-sync-calendar">Sincronizar Google Agenda</button>'+(googleState.calendarUrl?'<a class="link" href="'+esc(googleState.calendarUrl)+'" target="_blank" rel="noopener noreferrer">Abrir calendário ↗</a>':''):'<button class="secondary" data-user-settings>Configurar Google</button>')+'</div>'+(conflicts.length||errors.length?'<div class="google-sync-issues">'+[...conflicts,...errors].map(l=>'<div><p><strong>'+esc(projects.find(p=>p.id===l.projectId)?.title||'Projeto')+'</strong><br>'+esc(l.error)+'</p>'+(l.status==='conflito'?'<button class="secondary" data-google-force="'+l.projectId+'">Republicar versão do Studio</button>':'')+'</div>').join('')+'</div>':'')+'<p id="google-agenda-error" class="inline-error" role="alert" hidden></p><p class="help-text">O Studio envia prazos para o Google. Alterações no Google não modificam seus projetos. Você será avisado se houver conflito.</p></section>';}
function planningGoogleControls(plan,items,archived){const row=(googleState.forms||[]).find(f=>f.planId===plan.id&&f.accountEmail===googleState.email&&f.status==='publicado'),latest=(googleState.forms||[]).find(f=>f.planId===plan.id),connected=googleConnected();return '<div class="planning-share google-planning-share"><button class="primary" id="google-create-form" '+(!connected||!items.length||archived?'disabled':'')+'>'+(row?'Obter link Google Forms':'Gerar link Google Forms')+'</button><button class="secondary" id="google-sync-responses" '+(!connected||!row||archived?'disabled':'')+'>Atualizar aprovações</button>'+(!connected?'<button class="link" data-user-settings>Configurar Google ↗</button>':'')+'<p>'+esc(userProfile.formsUploadImages?'Miniaturas serão enviadas ao Drive e ficarão acessíveis por link.':'O formulário terá textos e links. Ative miniaturas no seu perfil se desejar.')+'</p></div>'+(row?'<div class="google-form-link"><label for="google-form-url">Link para enviar ao cliente</label><div><input id="google-form-url" readonly value="'+esc(row.responderUrl)+'"><button class="secondary" id="copy-google-form">Copiar link</button><a class="secondary" href="'+esc(row.responderUrl)+'" target="_blank" rel="noopener noreferrer">Abrir</a></div><button class="link danger-text" data-close-google-form="'+row.id+'">Encerrar recebimento de respostas</button><p class="help-text">Compartilhe somente o link de resposta. A identificação do cliente é declarada; quem receber o link poderá responder.</p></div>':'')+(latest&&latest.status!=='publicado'?'<p class="help-text">Último envio: '+esc(({desatualizado:'desatualizado — gere um novo link; o fechamento no Google ocorre na próxima sincronização',encerrado:'encerrado',erro:'não concluído',rascunho:'em preparação'})[latest.status]||latest.status)+'. '+esc(latest.error||'')+'</p>':'')+'<details class="offline-approval"><summary>Opções de arquivo (offline)</summary><div class="planning-share"><button class="secondary" id="export-plan" '+(!items.length||archived?'disabled':'')+'>Baixar para aprovação</button><label class="secondary import-label" for="import-approval">Importar respostas<input type="file" id="import-approval" accept=".json,application/json" '+(archived?'disabled':'')+'></label><p>Alternativa para uso sem conexão com o Google.</p></div></details>';}
function showGoogleError(e,hostId='google-error'){const el=document.getElementById(hostId);if(el){el.textContent=errorMessage(e);el.hidden=false}else toast(errorMessage(e));}
async function googleAction(action,extra={},silent=false){if(googleWorking){if(!silent)toast('Aguarde a operação com o Google terminar.');return}googleWorking=true;const buttons=[...document.querySelectorAll('[id^="google-"] button,button[id^="google-"],[data-google-force]')];const previousDisabled=buttons.map(b=>b.disabled);buttons.forEach(b=>b.disabled=true);try{const result=await request('google',{action,...extra});if(action==='connect'){location.assign(result.url);return result}await refresh();if(!silent){if(action==='syncCalendar')toast(result.synced+' projeto(s) sincronizado(s). '+result.conflicts+' conflito(s), '+result.errors+' erro(s).');else if(action==='syncResponses')toast(result.imported+' decisão(ões) atualizada(s). '+result.ignored+' resposta(s) ignorada(s).');else toast(result.warning||({saveCredentials:'Credenciais salvas. Agora conecte sua conta.',disconnect:'Conta desconectada.',createForm:'Link de aprovação pronto.',closeForm:'Formulário encerrado.'})[action]||'Operação concluída.');}return result;}catch(e){if(!silent)showGoogleError(e,view==='agenda'?'google-agenda-error':view==='planning'?'planning-error':'google-error');else{try{await refresh()}catch{}}}finally{googleWorking=false;buttons.forEach((b,i)=>{if(b.isConnected)b.disabled=previousDisabled[i]})}}
function scheduleGoogleSync(){clearTimeout(googleSyncTimer);if(!loaded||!userProfile.autoGoogleSync||!googleConnected()||document.hidden)return;googleSyncTimer=setTimeout(async()=>{if(busy||googleWorking){scheduleGoogleSync();return}await googleAction('syncCalendar',{},true);if(googleConnected())await googleAction('syncResponses',{},true);},1500)}
function handleGoogleReturn(){const result=new URLSearchParams(location.search).get('google');if(result){history.replaceState(null,'',location.pathname);navigate('account');toast(result==='connected'?'Conta Google conectada.':result==='cancelled'?'Conexão cancelada.':googleState.lastError||'Não foi possível conectar. Confira as instruções.');}}
setInterval(()=>{if(!document.hidden)scheduleGoogleSync()},60000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)scheduleGoogleSync()});
document.addEventListener('click',async e=>{const target=e.target.closest('button');if(!target)return;if(target.hasAttribute('data-user-settings'))navigate('account');if(target.id==='google-connect')googleAction('connect');if(target.id==='google-disconnect'&&confirm('Desconectar esta conta do Studio? Os eventos e formulários existentes permanecerão no Google.'))googleAction('disconnect');if(target.id==='google-sync-calendar')googleAction('syncCalendar');if(target.dataset.googleForce&&confirm('Republicar os dados do Studio sobre este evento? As alterações feitas nele no Google serão substituídas.'))googleAction('syncCalendar',{forceProjectId:Number(target.dataset.googleForce)});if(target.id==='google-create-form'&&currentPlan())googleAction('createForm',{planId:currentPlan().id});if(target.id==='google-sync-responses'&&currentPlan())googleAction('syncResponses',{planId:currentPlan().id});if(target.dataset.closeGoogleForm&&confirm('Encerrar as respostas deste formulário? O link deixará de aceitar novas respostas.'))googleAction('closeForm',{id:Number(target.dataset.closeGoogleForm)});if(target.id==='copy-google-form'){const field=document.getElementById('google-form-url');try{await navigator.clipboard.writeText(field.value);toast('Link copiado.')}catch{field.select();toast('Selecione e copie o link exibido.')}}});
document.addEventListener('submit',async e=>{if(e.target.id==='profile-form'){e.preventDefault();if(busy)return;busy=true;try{await request('profile',{name:document.getElementById('profile-name').value,studioName:document.getElementById('profile-studio').value,role:document.getElementById('profile-role').value,email:document.getElementById('profile-email').value,accent:document.getElementById('profile-accent').value,density:document.getElementById('profile-density').value,autoGoogleSync:document.getElementById('profile-auto-sync').checked,formsUploadImages:document.getElementById('profile-form-images').checked});await refresh();toast('Perfil e preferências salvos.');scheduleGoogleSync();}catch(err){showGoogleError(err,'profile-error')}finally{busy=false}}if(e.target.id==='google-credentials-form'){e.preventDefault();await googleAction('saveCredentials',{clientId:document.getElementById('google-client-id').value,clientSecret:document.getElementById('google-client-secret').value})}});
document.addEventListener('change',async e=>{if(e.target.id!=='google-credentials-file'||!e.target.files[0])return;try{const file=e.target.files[0];if(file.size>65536)throw new Error('Escolha o JSON de credenciais OAuth baixado do Google Cloud.');const json=JSON.parse(await file.text()),web=json.web;if(!web?.client_id||!web?.client_secret)throw new Error('O JSON deve ser do tipo Aplicativo da Web (campo web).');document.getElementById('google-client-id').value=web.client_id;document.getElementById('google-client-secret').value=web.client_secret;toast('Credenciais importadas. Clique Salvar credenciais.');}catch(err){showGoogleError(err instanceof SyntaxError?new Error('O arquivo não é um JSON válido.'):err)}finally{e.target.value=''}});
